      'DATABASE_URL = "postgres://localhost/app"',
      '_.file = ".env.local"',
    ],
    command: "mise env",
    output: ["export DATABASE_URL=postgres://localhost/app"],
    caption: "Your environment, ready when you cd.",
    link: "/environments/",
  },
